import { useReducer } from 'react';
import userReducer from './store';
import { BrowserRouter as Router, Route, Switch } from 'react-router-dom';
import Chat from './components/Chat/Chat';
import PythonGen from './components/PythonGen/PythonGen';
import UserPrompt from './components/UserPrompt/UserPrompt';

const App = () => {
  const [state, dispatch] = useReducer(userReducer, { prompt: '' });

  return (
    <div className="App">
      <Router>
        <Switch>
          <Route exact path="/" component={PythonGen} />
          <Route path="/userPrompt" component={() => <UserPrompt />} />
          <Route path="/chat" component={() => <Chat state={state} />} />
        </Switch>
      </Router>
    </div>
  );
};

export default App;
